<script setup lang="ts">import{ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{api}from'../api';import type{Post}from'../types';import PostCard from'../components/PostCard.vue';const route=useRoute(),router=useRouter(),items=ref<Post[]>([]),loading=ref(true),total=ref(0);async function load(){loading.value=true;const q=new URLSearchParams();['category','tag','page'].forEach(k=>{if(route.query[k])q.set(k,String(route.query[k]))});const x=await api<{items:Post[],total:number}>('/posts?'+q);items.value=x.items;total.value=x.total;loading.value=false}watch(()=>route.fullPath,load,{immediate:true});</script><template><section class="page-head"><p class="eyebrow">/ POSTS</p><h1>{{route.query.category||route.query.tag||'所有文章'}}</h1><p>共 {{total}} 篇已发布文章</p></section><p v-if="loading" class="state">正在载入文章…</p><p v-else-if="!items.length" class="state">这里暂时没有文章。</p><div v-else class="grid"><PostCard v-for="p in items" :post="p" :key="p.id"/></div><div class="pager"><button :disabled="Number(route.query.page||1)<=1" @click="router.push({...route,query:{...route.query,page:Number(route.query.page||1)-1}})">上一页</button><button :disabled="items.length<10" @click="router.push({...route,query:{...route.query,page:Number(route.query.page||1)+1}})">下一页</button></div></template>
